{
  "titre": "Supply and Demand Explained",
  "objectifGeneral": "Evaluate the accuracy of supply and demand analyses when applied to a real-world case study.",
  "notionsPivots": [
    "demand curve",
    "supply curve",
    "equilibrium price",
    "market forces",
    "scarcity"
  ],
  "etapes": [
    {
      "titre": "Discover at home",
      "objectif": "Identify core principles of supply and demand using provided resources.",
      "cartes": [
        {
          "titre": "Watch the instructional video",
          "objectif": "Explore fundamental supply and demand concepts",
          "module": "CoursePresentation",
          "palier": "decouverte",
          "duree": 20,
          "consigne": "Watch the 10-minute video explaining supply and demand curves, equilibrium price, and market forces. Note key terms in your notebook."
        },
        {
          "titre": "Complete the self-check quiz",
          "objectif": "Confirm understanding of supply and demand concepts",
          "module": "SingleChoiceSet",
          "palier": "decouverte",
          "duree": 10,
          "consigne": "Answer 5 multiple-choice questions based directly on the video content to verify comprehension."
        }
      ]
    },
    {
      "titre": "Apply in class",
      "objectif": "Collaboratively solve a supply and demand case study",
      "cartes": [
        {
          "titre": "Case study analysis",
          "objectif": "Solve a problem that required advanced application",
          "module": "Devoir",
          "palier": "transfert",
          "duree": 30,
          "consigne": "In small groups, analyze a real-world case study where supply constraints impact demand. Prepare graphical and written justifications for your solution to present."
        }
      ]
    },
    {
      "titre": "Review after class",
      "objectif": "Assess the accuracy of solutions and correct misconceptions",
      "cartes": [
        {
          "titre": "Mastery check",
          "objectif": "Demonstrate retained knowledge of supply and demand analysis",
          "module": "test_elea",
          "palier": "entrainement",
          "duree": 15,
          "consigne": "Complete a 10-question quiz that mixes graph interpretation and real-world application scenarios to evaluate your understanding."
        }
      ]
    }
  ]
}
